package ws.server

import java.util.concurrent.{ConcurrentHashMap, CountDownLatch}
import java.util.concurrent.atomic.{AtomicBoolean, AtomicInteger}
import scala.collection.mutable
import scala.concurrent.{ExecutionContext, Future, Promise}
import scala.util.{Try, Success, Failure}

trait WebSocketFrame {
  def payload: Array[Byte]
  def isClose: Boolean
}
case class TextFrame(payload: Array[Byte]) extends WebSocketFrame { def isClose = false }
case class CloseFrame(payload: Array[Byte], code: Int) extends WebSocketFrame { def isClose = true }

trait ConnectionHandler {
  def onMessage(frame: WebSocketFrame): Unit
  def onClose(): Unit
  def sendFrame(frame: WebSocketFrame): Future[Unit]
}

class SessionState {
  private val messageCount = new AtomicInteger(0)
  private val pendingWrites = new AtomicInteger(0)
  @volatile private var draining = false
  @volatile private var closed = false
  private val closeCallbacks = mutable.ListBuffer[() => Unit]()
  private val lock = new Object

  def incrementMessages(): Int = messageCount.incrementAndGet()
  def getPendingWrites(): Int = pendingWrites.get()
  def incrementPending(): Int = pendingWrites.incrementAndGet()
  def decrementPending(): Int = pendingWrites.decrementAndGet()

  def isDraining: Boolean = draining
  def isClosed: Boolean = closed

  def beginDrain(): Boolean = lock.synchronized {
    if (!draining && !closed) {
      draining = true
      true
    } else false
  }

  def registerCloseCallback(cb: () => Unit): Unit = lock.synchronized {
    if (!closed) {
      closeCallbacks += cb
    } else {
      cb()
    }
  }

  def finalizeClose(): List[() => Unit] = lock.synchronized {
    closed = true
    val cbs = closeCallbacks.toList
    closeCallbacks.clear()
    cbs
  }
}

class GracefulShutdownManager(implicit ec: ExecutionContext) {
  private val sessions = new ConcurrentHashMap[String, (SessionState, ConnectionHandler)]()
  private val shuttingDown = new AtomicBoolean(false)
  private val shutdownLatch = new CountDownLatch(1)

  def registerSession(id: String, state: SessionState, handler: ConnectionHandler): Unit = {
    sessions.put(id, (state, handler))
  }

  def removeSession(id: String): Unit = {
    sessions.remove(id)
    if (shuttingDown.get() && sessions.isEmpty) {
      shutdownLatch.countDown()
    }
  }

  def initiateShutdown(): Future[Unit] = {
    shuttingDown.set(true)
    val promise = Promise[Unit]()

    Future {
      val entries = new java.util.ArrayList(sessions.entrySet())
      val iter = entries.iterator()
      while (iter.hasNext) {
        val entry = iter.next()
        val (state, handler) = entry.getValue
        drainAndClose(entry.getKey, state, handler)
      }
      shutdownLatch.await()
      promise.success(())
    }

    promise.future
  }

  private def drainAndClose(id: String, state: SessionState, handler: ConnectionHandler): Unit = {
    if (state.beginDrain()) {
      waitForPendingAndClose(id, state, handler)
    }
  }

  private def waitForPendingAndClose(id: String, state: SessionState, handler: ConnectionHandler): Unit = {
    if (state.getPendingWrites() > 0) {
      state.registerCloseCallback(() => {
        waitForPendingAndClose(id, state, handler)
      })
    } else {
      performClose(id, state, handler)
    }
  }

  private def performClose(id: String, state: SessionState, handler: ConnectionHandler): Unit = {
    val callbacks = state.finalizeClose()
    handler.onClose()
    removeSession(id)
    // Execute any callbacks that were registered between drain check and close
    callbacks.foreach(cb => cb())
  }
}

class WebSocketConnection(id: String, state: SessionState, manager: GracefulShutdownManager)(
  implicit ec: ExecutionContext
) extends ConnectionHandler {

  private val outputQueue = mutable.Queue[WebSocketFrame]()
  private val writeLock = new Object

  override def onMessage(frame: WebSocketFrame): Unit = {
    if (state.isClosed) return
    if (frame.isClose) {
      manager.removeSession(id)
      return
    }
    state.incrementMessages()
    // Echo back with processing
    val response = TextFrame(frame.payload.map(b => (b ^ 0x20).toByte))
    sendFrame(response)
  }

  override def onClose(): Unit = {
    writeLock.synchronized {
      outputQueue.clear()
    }
  }

  override def sendFrame(frame: WebSocketFrame): Future[Unit] = {
    if (state.isDraining && !frame.isClose) {
      return Future.successful(())
    }
    state.incrementPending()
    val promise = Promise[Unit]()

    Future {
      writeLock.synchronized {
        outputQueue.enqueue(frame)
      }
      // Simulate async write completion
      Thread.sleep(1)
      val remaining = state.decrementPending()
      promise.success(())

      // Notify drain waiters when pending reaches zero
      if (remaining == 0 && state.isDraining) {
        val callbacks = state.finalizeClose()
        callbacks.foreach(cb => cb())
      }
    }

    promise.future
  }
}

object WebSocketServer {
  def createConnection(id: String, manager: GracefulShutdownManager)(
    implicit ec: ExecutionContext
  ): WebSocketConnection = {
    val state = new SessionState()
    val conn = new WebSocketConnection(id, state, manager)
    manager.registerSession(id, state, conn)
    conn
  }
}
